#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <algorithm>
using namespace std;

const int MAXN = 210;
const int INF = 0x3f3f3f3f;

struct FlowSolver {
    int capacity[MAXN][MAXN], flow[MAXN][MAXN], adj[MAXN][MAXN], degree[MAXN];
    int totalNodes, s, t;
    int height[MAXN], countH[MAXN];

    void setup(int n) {
        totalNodes = n;
        memset(capacity, 0, sizeof(capacity));
        memset(adj, 0, sizeof(adj));
        for (int i = 0; i <= n; i++) degree[i] = 0;
        memset(height, 0, sizeof(height));
        memset(countH, 0, sizeof(countH));
    }

    void addEdge(int u, int v, int c) {
        capacity[u][v] += c;
        if (!adj[u][v]) { adj[u][v] = 1; degree[u]++; }
    }

    int pushFlow(int u, int flowIn) {
        if (u == t) return flowIn;
        int totalFlow = 0;
        for (int v = 0; v < totalNodes; v++) {
            if (capacity[u][v] - flow[u][v] > 0 && height[u] == height[v] + 1) {
                int pushed = min(flowIn, capacity[u][v] - flow[u][v]);
                int pushedAmount = pushFlow(v, pushed);
                if (pushedAmount > 0) {
                    flow[u][v] += pushedAmount;
                    flow[v][u] -= pushedAmount;
                    totalFlow += pushedAmount;
                    flowIn -= pushedAmount;
                    if (flowIn == 0) break;
                }
            }
        }
        if (totalFlow == 0) {
            int minH = totalNodes;
            for (int v = 0; v < totalNodes; v++) {
                if (capacity[u][v] - flow[u][v] > 0) minH = min(minH, height[v]);
            }
            if (--countH[height[u]] == 0) height[s] = totalNodes;
            height[u] = minH + 1;
            countH[height[u]]++;
        }
        return totalFlow;
    }

    int computeMaxFlow(int s_, int t_) {
        s = s_; t = t_;
        memset(flow, 0, sizeof(flow));
        memset(height, 0, sizeof(height));
        memset(countH, 0, sizeof(countH));
        for (int i = 0; i <= totalNodes; i++) height[i] = 0;
        countH[0] = totalNodes;
        int totalFlow = 0;
        while (height[s] < totalNodes) {
            totalFlow += pushFlow(s, INF);
        }
        return totalFlow;
    }
};

struct Cell {
    int row, col, dist;
};

int n, T;
int startX, startY;
int dirX[4] = {0, 0, -1, 1};
int dirY[4] = {-1, 1, 0, 0};
char gridA[210][210], gridB[210][210];
int distMap[210][210], visited[210][210];

int getID(int i, int j) {
    return (i - 1) * n + j;
}

bool validPos(int x, int y) {
    return x >= 1 && x <= n && y >= 1 && y <= n;
}

void computeDist1() {
    queue<Cell> q;
    Cell c, nc;
    c.row = startX; c.col = startY; c.dist = 0;
    q.push(c);
    memset(distMap, 0x7f, sizeof(distMap));
    memset(visited, 0, sizeof(visited));
    visited[startX][startY] = 1;
    while (!q.empty()) {
        c = q.front(); q.pop();
        distMap[c.row][c.col] = c.dist;
        if (c.dist > T) break;
        for (int k = 0; k < 4; k++) {
            int nx = c.row + dirX[k], ny = c.col + dirY[k];
            if (validPos(nx, ny) && gridA[nx][ny] != 'Y' && !visited[nx][ny]) {
                nc.row = nx; nc.col = ny; nc.dist = c.dist + 1;
                visited[nx][ny] = 1;
                q.push(nc);
            }
        }
    }
}

void computeDist2(int i, int j) {
    queue<Cell> q;
    Cell c, nc;
    c.row = i; c.col = j; c.dist = 0;
    memset(visited, 0, sizeof(visited));
    visited[i][j] = 1;
    q.push(c);
    while (!q.empty()) {
        c = q.front(); q.pop();
        if (c.dist > T) break;
        if (distMap[c.row][c.col] < c.dist) continue;
        if ((distMap[c.row][c.col] == c.dist && gridB[c.row][c.col] < '1') || gridB[c.row][c.col] > '9') continue;
        if (gridB[c.row][c.col] >= '1' && gridB[c.row][c.col] <= '9') {
            if (c.row != i || c.col != j)
                solver.addEdge(getID(i, j), getID(c.row, c.col) + n * n, INF);
            if (distMap[c.row][c.col] == c.dist) continue;
        }
        for (int k = 0; k < 4; k++) {
            int nx = c.row + dirX[k], ny = c.col + dirY[k];
            if (validPos(nx, ny) && gridA[nx][ny] != 'Y' && !visited[nx][ny]) {
                nc.row = nx; nc.col = ny; nc.dist = c.dist + 1;
                visited[nx][ny] = 1;
                q.push(nc);
            }
        }
    }
}

int main() {
    scanf("%d%d", &n, &T);
    for (int i = 1; i <= n; i++) scanf("%s", gridA[i] + 1);
    for (int i = 1; i <= n; i++) scanf("%s", gridB[i] + 1);
    int s = 0, e = 2 * n * n + 1;
    solver.setup(e + 1);
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (gridA[i][j] >= '1' && gridA[i][j] <= '9') {
                solver.addEdge(s, getID(i, j), gridA[i][j] - '0');
            }
            if (gridA[i][j] == 'Z') {
                startX = i; startY = j;
            }
        }
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            solver.addEdge(getID(i, j), getID(i, j) + n * n, INF);
            if (gridB[i][j] >= '1' && gridB[i][j] <= '9') {
                solver.addEdge(getID(i, j) + n * n, e, gridB[i][j] - '0');
            }
        }
    }
    computeDist1();
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (gridA[i][j] >= '1' && gridA[i][j] <= '9') computeDist2(i, j);
        }
    }
    int res = solver.computeMaxFlow(s, e);
    printf("%d\n", res);
}
